					fLookups = GetNewLookups();
				}

				return fLookups;
			}
		}

		protected virtual CNAddInfoLookups GetNewLookups()
		{
			return new CNAddInfoLookups(this);
		}

		CNAddInfoLookups fLookups;

		#endregion

		#region Validation

		protected override void RunPreSaveValidationCore()
		{
			Validation.ValidateAll();
			base.RunPreSaveValidationCore(); // call RunPreSaveValidationCore() on all children then fire OnNotificationsChanged()
		}

		public CNAddInfoValidation Validation
		{
			get { return GetNewValidation(); }
		}

		protected virtual CNAddInfoValidation GetNewValidation()
		{
			return new CNAddInfoValidation(this);
		}

		#endregion
	}
}
